nativeVerticalThumbRule:
min-height: var(--ore-scrollbar-thumb-min-size);
border-radius: 0;
background:
  linear-gradient(
      var(--ore-scrollbar-thumb-background),
      var(--ore-scrollbar-thumb-background)
    )
    center calc(var(--ore-scrollbar-unit) * 2) /
    calc(100% - var(--ore-scrollbar-unit) * 4)
    calc(100% - var(--ore-scrollbar-unit) * 6) no-repeat,
  linear-gradient(
      var(--ore-scrollbar-thumb-shadow),
      var(--ore-scrollbar-thumb-shadow)
    )
    center bottom var(--ore-scrollbar-unit) /
    calc(100% - var(--ore-scrollbar-unit) * 2)
    calc(var(--ore-scrollbar-unit) * 2) no-repeat,
  linear-gradient(
      var(--ore-scrollbar-thumb-highlight),
      var(--ore-scrollbar-thumb-highlight)
    )
    center var(--ore-scrollbar-unit) /
    calc(100% - var(--ore-scrollbar-unit) * 2)
    calc(100% - var(--ore-scrollbar-unit) * 4) no-repeat,
  var(--ore-scrollbar-thumb-border);

nativeVerticalTrackRule:
background: linear-gradient(
    var(--ore-scrollbar-track),
    var(--ore-scrollbar-track)
  )
  center / var(--ore-scrollbar-track-size) 100% no-repeat;
